// Parse OpenAI response and format for LinkedIn
const response = $json.text;
let summary, hashtags;

try {
  // Try to parse JSON response
  const parsed = JSON.parse(response);
  summary = parsed.summary;
  hashtags = parsed.hashtags;
} catch (error) {
  // Fallback: extract summary and hashtags from text
  const lines = response.split('\n');
  summary = lines.find(line => line.includes('summary') || line.includes('Summary')) || response;
  hashtags = response.match(/#\w+/g)?.join(' ') || '#News #Technology';
}

// Clean up summary
summary = summary.replace(/^.*?summary.*?:/i, '').trim();
summary = summary.replace(/^.*?Summary.*?:/i, '').trim();

// Ensure hashtags are properly formatted
if (!hashtags.startsWith('#')) {
  hashtags = '#' + hashtags.replace(/^#/, '');
}

// Build LinkedIn post
const postText = `🧠 ${$('Filter Content Quality').item.json.title}\n\n${summary}\n\nSource: ${$('Filter Content Quality').item.json.link}\n\n${hashtags}`;

// Check character limit
if (postText.length > 3000) {
  // Truncate summary if needed
  const maxSummaryLength = 3000 - postText.length + summary.length;
  summary = summary.substring(0, maxSummaryLength - 3) + '...';
}

return {
  json: {
    title: $('Filter Content Quality').item.json.title,
    link: $('Filter Content Quality').item.json.link,
    summary: summary,
    hashtags: hashtags,
    postText: postText,
    characterCount: postText.length,
    source: $('Filter Content Quality').item.json.source || 'RSS Feed'
  }
};

// For testing, just log the post instead of actually posting to LinkedIn
const postData = $json;

console.log('=== LINKEDIN POST (TEST MODE) ===');
console.log('Title:', postData.title);
console.log('Summary:', postData.summary);
console.log('Hashtags:', postData.hashtags);
console.log('Character Count:', postData.characterCount);
console.log('Full Post Text:');
console.log(postData.postText);
console.log('================================');

// Return success response
return {
  json: {
    success: true,
    message: 'Post would be published to LinkedIn (test mode)',
    postId: 'test-' + Date.now(),
    ...postData
  }
};
